"""Bounded expression expansion: add/multiply powers of u, degree <=2.
Coefficient fit uses CAL/U1/U2 only; U3 is an unused validation observation.
No claim of discovering a representation language or universal causal law.
"""
import json
from fractions import Fraction as F
from agenda_runtime import AgendaRuntime

def evaluate(coefficients,u):
    return sum(F(c)*u**i for i,c in enumerate(coefficients))

def construct(samples,degree):
    # Solve coefficients of powers generated by repeated multiplication of u.
    rows=[[F(u)**i for i in range(degree+1)]+[F(y)] for u,y in samples]
    if len(rows)!=degree+1:raise ValueError('wrong fitting set')
    for col in range(degree+1):
        pivot=next(i for i in range(col,len(rows)) if rows[i][col])
        rows[col],rows[pivot]=rows[pivot],rows[col]
        scale=rows[col][col];rows[col]=[x/scale for x in rows[col]]
        for i in range(len(rows)):
            if i!=col:
                scale=rows[i][col];rows[i]=[a-scale*b for a,b in zip(rows[i],rows[col])]
    return tuple(str(row[-1]) for row in rows)

class StructureRuntime(AgendaRuntime):
    def __init__(self,*args,expand=True,**kwargs):
        super().__init__(*args,**kwargs);self.expand=expand
        self.db.execute('CREATE TABLE IF NOT EXISTS expressions(id INTEGER PRIMARY KEY,task_id INTEGER UNIQUE,body TEXT)')
        self.db.commit()

    def remembered(self):
        row=self.db.execute('SELECT body FROM expressions ORDER BY id DESC LIMIT 1').fetchone()
        return tuple(json.loads(row[0])['coefficients']) if row else None

    def predict_model(self,model,probe):
        value=evaluate(model,0 if probe=='CAL' else int(probe[1:]))
        return int(value) if value.denominator==1 else float(value)

    def fitted(self,s):
        e={x['probe']:x['value'] for x in s['evidence']}
        if not {'CAL','U1','U2'}<=e.keys():return None
        linear=construct([(0,e['CAL']),(1,e['U1'])],1)
        if all(evaluate(linear,0 if p=='CAL' else int(p[1:]))==y for p,y in e.items()):return linear
        if not self.expand or 'U3' not in e:return None
        quadratic=construct([(0,e['CAL']),(1,e['U1']),(2,e['U2'])],2)
        return quadratic if evaluate(quadratic,3)==e['U3'] else None

    def candidates(self,s):
        fit=self.fitted(s)
        if fit:return (fit,)
        model=self.remembered();e={x['probe']:x['value'] for x in s['evidence']}
        if model and 'CAL' in e and any(p in e for p in ('U1','U2')) and all(
                self.predict_model(model,p)==y for p,y in e.items()):return (model,)
        return ()

    def permitted_action(self,s,models):
        seen={e['probe'] for e in s['evidence']}
        return next((u for u in s['actions'] if 'U'+str(u) in seen and models and all(
            evaluate(m,u)-evaluate(m,0)==s['target'] for m in models)),None)

    def permit(self,u):
        s=self.state()
        if s['phase']!='ACT' or s['budget']<1 or not s['trusted']:return None
        if self.permitted_action(dict(s,actions=[u]),self.candidates(s))!=u or u not in s['actions']:return None
        return dict(u=u,generation=s['generation'],task_id=s['task_id'],target=s['target'],
                    basis_versions={k:v[1] for k,v in self.beliefs().items()})

    def choose_plan(self,s,models):
        u=self.permitted_action(s,models)
        if u is not None and s['budget']>=1:return ('ACT',u),'checked-expression'
        seen={e['probe'] for e in s['evidence']}
        if self.fitted(s) or 'U3' in seen or (not self.expand and {'CAL','U1','U2'}<=seen):
            return ('HALT',None),'model-inadequate-or-target-infeasible'
        if s['budget']<2:return ('HALT',None),'insufficient-budget'
        model=self.remembered()
        proposed=next((u for u in s['actions'] if model and evaluate(model,u)-evaluate(model,0)==s['target']),None)
        consistent=model and all(self.predict_model(model,e['probe'])==e['value'] for e in s['evidence'])
        order=('CAL','U'+str(proposed),'U1','U2','U3') if consistent and proposed else ('CAL','U1','U2','U3')
        return ('PROBE',next(p for p in order if p not in seen)),'bounded-structural-inquiry'

    def commit_complete_evidence(self,s):
        e={x['probe']:x['value'] for x in s['evidence']}
        if not {'CAL','U1','U2'}<=e.keys():return
        linear=construct([(0,e['CAL']),(1,e['U1'])],1)
        if evaluate(linear,2)!=e['U2']:
            self.event(s,'AFFINE_CLASS_GAP',fitting=['CAL','U1'],failed_check='U2')
        model=self.fitted(s)
        if model is None or not s['trusted']:return
        if self.db.execute('SELECT 1 FROM expressions WHERE task_id=?',(s['task_id'],)).fetchone():return
        quadratic=len(model)==3
        record=dict(coefficients=model,grammar='sum(coeff[i]*u**i), degree<=2',
                    fitting_probes=['CAL','U1','U2'] if quadratic else ['CAL','U1'],
                    validation_probe='U3' if quadratic else 'U2',evidence=s['evidence'])
        old=self.remembered()
        self.db.execute('INSERT INTO expressions(task_id,body) VALUES(?,?)',(s['task_id'],json.dumps(record)))
        # process value remains legacy affine metadata; expression is authoritative here.
        if old is None or old[1:]!=model[1:]:self.db.execute("UPDATE beliefs SET version=version+1 WHERE name='process'")
        bias=int(F(model[0]))
        if self.beliefs()['sensor'][0]!=bias:
            self.db.execute("UPDATE beliefs SET value=?,version=version+1 WHERE name='sensor'",(bias,))
        self.db.execute('UPDATE forecasts SET valid=0')
        self.db.execute('INSERT INTO runtime_revisions(body) VALUES(?)',(json.dumps(record),))
        self.event(s,'EXPRESSION_VALIDATED',record=record)
